from rdflib import Graph

g = Graph()
g.parse("/app/university_graph.ttl", format="turtle")

# Test if rdflib supports subqueries in FILTER EXISTS with aggregation
query = """
PREFIX uni: <http://university.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema/>

SELECT ?professorName
WHERE {
  ?professor a uni:Person ;
             uni:hasName ?professorName ;
             uni:role ?role ;
             uni:worksIn ?dept .
  FILTER (STRSTARTS(?role, "Professor") && !STRSTARTS(?role, "Assistant Professor"))

  # Student enrollment check: at least one dept has >10 active students
  FILTER EXISTS {
    SELECT ?dept
    WHERE {
      ?professor uni:worksIn ?dept .
      ?course uni:isTaughtIn ?dept .
      ?student uni:isEnrolledIn ?course ;
               uni:hasEnrollmentDate ?enrollDate .
      FILTER (?enrollDate < "2025-08-16"^^xsd:date)
      OPTIONAL { ?student uni:hasGraduationDate ?gradDate }
      FILTER (!BOUND(?gradDate) || ?gradDate >= "2025-08-16"^^xsd:date)
    }
    GROUP BY ?dept
    HAVING (COUNT(DISTINCT ?student) > 10)
  }
}
"""

try:
    results = g.query(query)
    for row in results:
        print(f"Name: {row.professorName}")
except Exception as e:
    print(f"Error: {e}")
